/**
 * The Java assertClose: a relative tolerance floored at `rel` so values near
 * zero are not held to an impossible standard. The label identifies the
 * assertion, which the reported line number cannot.
 */
void assertClose(const char *what, double expected, double actual, double rel) {
    double tol = std::fmax(rel, std::abs(expected) * rel);
    if (!(std::abs(actual - expected) <= tol))
        ::redukti::test::reportFailure(
            __FILE__, __LINE__,
            std::string(what) + ": got " + doubleToString(actual) + " want " +
                doubleToString(expected) + " tol " + doubleToString(tol));
}

/**
 * Ends the test, the way a failed JUnit assertion ends the Java method. Only
 * the structural checks below use it: a wrong segment count means the indexing
 * that follows would run off the end of the vector.
 */
struct AbortTest {};

void assertCount(const char *what, std::size_t expected, std::size_t actual) {
    if (expected != actual) {
        ::redukti::test::reportFailure(
            __FILE__, __LINE__,
            std::string(what) + ": got " + std::to_string(actual) + " want " +
                std::to_string(expected));
        throw AbortTest();
    }
}

void assertHasValue(const char *what, bool present) {
    if (!present)
        ::redukti::test::reportFailure(__FILE__, __LINE__,
                                       std::string(what) + ": expected a value");
}

/** An absent aim_info reads as NaN so the assertion fails instead of the read. */
double aim_or_nan(const std::unique_ptr<specs::Field> &fld, std::size_t i) {
    if (!fld->aim_info.has_value())
        return NAN;
    return (*fld->aim_info)[i];
}

void accumulate(std::array<double, 5> &into, const std::array<double, 5> &add) {
    for (std::size_t i = 0; i < into.size(); i++)
        into[i] += add[i];
}


