void chief_ray_aiming() {
    auto _m = build();
    const auto &fields = _m->optical_spec->fov->fields;
    assertHasValue("aim.0.z_enp - expected wide angle aiming", fields[0]->z_enp.has_value());
    assertClose("aim.0.z_enp", 27.626816277573248, fields[0]->z_enp.value_or(NAN), 1.0e-6);
    assertHasValue("aim.1.z_enp - expected wide angle aiming", fields[1]->z_enp.has_value());
    assertClose("aim.1.z_enp", 31.732158103741654, fields[1]->z_enp.value_or(NAN), 1.0e-6);
    assertHasValue("aim.2.z_enp - expected wide angle aiming", fields[2]->z_enp.has_value());
    assertClose("aim.2.z_enp", 38.79449545380068, fields[2]->z_enp.value_or(NAN), 1.0e-6);
}

